def cmd(args,t=14):
 return subprocess.run(args,capture_output=True,text=True,timeout=t,env={**os.environ,'GIT_PAGER':'cat','PAGER':'cat'})
def git(path,*args):
 return cmd(['sudo','-n','-u',owner,'git','-C',str(path),*args],18)
def state(s):
 return cmd(['systemctl','is-active',s+'.service'],8).stdout.strip()
def bots():
 r=cmd(['pm2','jlist'],14)
 if r.returncode:raise RuntimeError('PM2 cannot verify')
 return {a.get('name'):(a.get('pm2_env') or {}).get('status') for a in json.loads(r.stdout)}
protected=['lowcost-europa','pink-iptv-backend','pink-vpn','fadego-staging','pm2-root','nginx','postgresql@16-main','ssh']
old_state={x:state(x) for x in protected}
if any(v!='active' for v in old_state.values()):raise RuntimeError('Protected service not active')
if any(bots().get(x)!='online' for x in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram bot not online')
if not src.is_dir() or src.is_symlink() or not parent.is_dir() or dst.exists() or dst.is_symlink() or src.stat().st_dev!=parent.stat().st_dev:
 raise RuntimeError('Project path preflight failed')
owner=pwd.getpwuid(src.stat().st_uid).pw_name
print('GIT_PROJECT_OWNER='+owner)
r=git(src,'remote','get-url','origin')
if r.returncode or 'martaxi-boss/lowcost-europa' not in r.stdout:raise RuntimeError('Repo owner Git remote validation failed')
r=git(src,'status','--porcelain','--untracked-files=no')
if r.returncode:raise RuntimeError('Git owner preflight failed: '+r.stderr[:220])
before_git=r.stdout
measure=cmd(['du','-x','-s','-B1',str(src)],40)
if measure.returncode:raise RuntimeError('Size unavailable')
before_sz=int(measure.stdout.split()[0]);inode=src.stat().st_ino
svc=cmd(['systemctl','show','lowcost-europa.service','-p','MainPID','-p','WorkingDirectory','--no-pager'],11)
info=dict(line.split('=',1) for line in svc.stdout.splitlines() if '=' in line)
pid=info.get('MainPID','0')
if info.get('WorkingDirectory')!=str(src) or not pid.isdigit() or int(pid)<=0:raise RuntimeError('Active service does not use this path')
moved=False
try:
 src.rename(dst);moved=True;src.symlink_to(dst,target_is_directory=True)
 if not src.is_symlink() or src.resolve()!=dst or dst.stat().st_ino!=inode:raise RuntimeError('Physical canonical relocation invalid')
 r=cmd([str(dst/'.venv/bin/python'),'-c','import sys; assert sys.version_info.major == 3'],16)
 if r.returncode:raise RuntimeError('Python interpreter not working at new path')
 after=git(dst,'status','--porcelain','--untracked-files=no')
 if after.returncode:
  print('GIT_OWNER_ERROR_CLASS='+after.stderr[:250].replace('\n',' '))
  raise RuntimeError('Git status after relocation could not run as owner')
 if after.stdout!=before_git:
  print('GIT_BEFORE_FILES='+str(before_git.splitlines()[:20]))
  print('GIT_AFTER_FILES='+str(after.stdout.splitlines()[:20]))
  raise RuntimeError('Tracked Git content changed during relocation')
 size=cmd(['du','-x','-s','-B1',str(dst)],40)
 if size.returncode or int(size.stdout.split()[0])!=before_sz:raise RuntimeError('Byte size mismatch')
 now_pid=cmd(['systemctl','show','lowcost-europa.service','-p','MainPID','--no-pager'],8).stdout.strip()
 if now_pid!='MainPID='+pid:raise RuntimeError('Lowcost process PID changed')
 for name,value in old_state.items():
  if state(name)!=value:raise RuntimeError('Service state changed '+name)
 if any(bots().get(x)!='online' for x in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Telegram bot offline')
except Exception:
 if src.is_symlink() and src.resolve()==dst:src.unlink()
 if moved and dst.is_dir() and not src.exists():dst.rename(src)
 print('LOWCOST_ROLLBACK=APPLIED')
 raise
print('CANONICAL_REAL_PATH='+str(dst))
print('OLD_SYMLINK_PATH='+str(src))
print('BYTES_MOVED='+str(before_sz))
print('OWNER_GIT_VALIDATION=PASS')
print('LOWCOST_PID_PRESERVED='+pid)
print('PROTECTED_SERVICES_ACTIVE=YES')
print('TELEGRAM_BOTS_ONLINE=YES')
print('DISK_FREE_GAIN_BYTES=0')
print('LOWCOST_PHYSICAL_MOVE=PASS')
